    hints: [{ dx: 'Carcinoma oesophagus', why: 'Progressive dysphagia to solids then liquids with marked weight loss.', any: ['progressive dysphagia to solids', 'weight loss', 'smoking, alcohol', 'hoarseness'] }, { dx: 'Achalasia cardia', why: 'Dysphagia to solids and liquids from the start with regurgitation and a bird-beak barium.', any: ['solids and liquids from the start', 'regurgitation of undigested', 'bird-beak'], min: 1 }],
    must: [['Progression of dysphagia', 'progressive dysphagia'], ['Weight loss', 'weight loss'], ['Risk factors', 'smoking, alcohol'], ['Cervical nodes', 'cervical lymph nodes'], ['Barium swallow', 'barium swallow'], ['Endoscopy with biopsy', 'endoscopy']],
    viva: [['Causes of dysphagia?', 'Luminal (foreign body), mural (carcinoma, stricture, achalasia), extramural (goitre, mediastinal nodes, aortic aneurysm).'], ['Types of oesophageal carcinoma?', 'Squamous (middle third, India) and adenocarcinoma (lower third, Barrett).'], ['Treatment?', 'Oesophagectomy for resectable disease; chemoradiotherapy; stenting for palliation.'], ['Achalasia treatment?', 'Pneumatic dilatation, laparoscopic Heller myotomy with partial fundoplication, POEM.'], ['Manometry in achalasia?', 'Incomplete relaxation of the lower oesophageal sphincter with absent peristalsis.'], ['Plummer-Vinson syndrome?', 'Dysphagia, iron deficiency anaemia and postcricoid web.']],
